CREATE TABLE IF NOT EXISTS schema_version(version INTEGER PRIMARY KEY);
INSERT OR IGNORE INTO schema_version VALUES(1);
CREATE TABLE IF NOT EXISTS sources(id TEXT PRIMARY KEY,scope TEXT NOT NULL,body TEXT NOT NULL,synthetic INTEGER NOT NULL CHECK(synthetic IN (0,1)),revision INTEGER NOT NULL DEFAULT 1,deleted INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS nodes(id TEXT PRIMARY KEY,source_id TEXT REFERENCES sources(id),content TEXT NOT NULL,epistemic TEXT NOT NULL,review TEXT NOT NULL,content_version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS organization(node_id TEXT PRIMARY KEY REFERENCES nodes(id),modules TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS layouts(node_id TEXT PRIMARY KEY REFERENCES nodes(id),x REAL,y REAL,z REAL,version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS runs(id TEXT PRIMARY KEY,kind TEXT NOT NULL,snapshot TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS proposals(id TEXT PRIMARY KEY,node_id TEXT REFERENCES nodes(id),payload TEXT NOT NULL,deps TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',accepted_by TEXT);
